#include <stdio.h>
#include <stdlib.h>

typedef struct Stream {
    int (*next_val)(struct Stream*);
    void *state;
    struct Stream *next;
} Stream;

typedef struct { int *arr; int len; int pos; } ArrayState;

int array_next(Stream *s) {
    ArrayState *st = (ArrayState*)s->state;
    return st->pos < st->len ? st->arr[st->pos++] : -1;
}

Stream* stream_from_array(int *arr, int len) {
    Stream *s = malloc(sizeof(Stream));
    ArrayState *st = malloc(sizeof(ArrayState));
    st->arr = arr; st->len = len; st->pos = 0;
    s->next_val = array_next; s->state = st; s->next = NULL;
    return s;
}

typedef struct { Stream *prev; int (*fn)(int); } MapState;

int map_next(Stream *s) {
    MapState *st = (MapState*)s->state;
    int val = st->prev->next_val(st->prev);
    return val == -1 ? -1 : st->fn(val);
}

Stream* stream_map(Stream *prev, int (*fn)(int)) {
    Stream *s = malloc(sizeof(Stream));
    MapState *st = malloc(sizeof(MapState));
    st->prev = prev; st->fn = fn;
    s->next_val = map_next; s->state = st;
    return s;
}

void stream_collect(Stream *s) {
    int val;
    while ((val = s->next_val(s)) != -1) printf("%d ", val);
    printf("\n");
}

int main() {
    int arr[] = {1, 2, 3, 4, 5};
    Stream *s = stream_from_array(arr, 5);
    stream_collect(s);
    return 0;
}
